export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  [key: string]: unknown;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  slug: string;
  sourcePath: string;
  outputPath: string;
  isDraft: boolean;
}

export interface TagIndex {
  tag: string;
  pages: Page[];
}

export interface BuildContext {
  pages: Page[];
  tags: Map<string, Page[]>;
  config: SiteConfig;
}

export interface SiteConfig {
  title: string;
  description: string;
  baseUrl: string;
  sourceDir: string;
  templateDir: string;
  outputDir: string;
}

import fs from "node:fs/promises";
import path from "node:path";
import matter from "gray-matter";
import type { Frontmatter, Page } from "./types.js";

function slugify(filePath: string, sourceDir: string): string {
  const rel = path.relative(sourceDir, filePath);
  const parsed = path.parse(rel);
  const slug = path.join(parsed.dir, parsed.name);
  return slug || "index";
}

export function parseFrontmatter(content: string): {
  data: Frontmatter;
  content: string;
} {
  const parsed = matter(content);
  const raw = parsed.data as Record<string, unknown>;

  const data: Frontmatter = {
    title: String(raw.title ?? "Untitled"),
  };

  if (raw.date) {
    data.date = String(raw.date);
  }
  if (raw.tags) {
    if (Array.isArray(raw.tags)) {
      data.tags = raw.tags.map(String);
    } else {
      data.tags = String(raw.tags).split(",").map((s) => s.trim());
    }
  }
  if (raw.draft !== undefined) {
    data.draft = Boolean(raw.draft);
  }

  for (const [key, value] of Object.entries(raw)) {
    if (!["title", "date", "tags", "draft"].includes(key)) {
      data[key] = value;
    }
  }

  return { data, content: parsed.content };
}

export async function parseFile(
  filePath: string,
  sourceDir: string,
  outputDir: string,
): Promise<Page> {
  const raw = await fs.readFile(filePath, "utf-8");
  const { data, content } = parseFrontmatter(raw);
  const slug = slugify(filePath, sourceDir);
  const ext = path.extname(filePath);

  return {
    frontmatter: data,
    content,
    html: "",
    slug,
    sourcePath: filePath,
    outputPath: path.join(outputDir, slug + ".html"),
    isDraft: data.draft === true,
  };
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return code;
    },
  }),
);

marked.setOptions({
  gfm: true,
  breaks: false,
});

export function renderMarkdown(content: string): string {
  return marked.parse(content) as string;
}

import fs from "node:fs/promises";
import path from "node:path";
import Handlebars from "handlebars";
import type { Page, TagIndex, SiteConfig } from "./types.js";

async function loadTemplates(templateDir: string): Promise<{
  templates: Map<string, HandlebarsTemplateDelegate>;
  partials: Map<string, string>;
}> {
  const templates = new Map<string, HandlebarsTemplateDelegate>();
  const partials = new Map<string, string>();

  const entries = await fs.readdir(templateDir, { withFileTypes: true });
  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith(".hbs")) {
      continue;
    }
    const filePath = path.join(templateDir, entry.name);
    const source = await fs.readFile(filePath, "utf-8");
    const name = path.parse(entry.name).name;

    if (name.startsWith("_")) {
      partials.set(name.slice(1), source);
    } else {
      templates.set(name, Handlebars.compile(source));
    }
  }

  return { templates, partials };
}

export async function compileTemplates(templateDir: string): Promise<{
  templates: Map<string, HandlebarsTemplateDelegate>;
  partials: Map<string, string>;
}> {
  const result = await loadTemplates(templateDir);

  for (const [name, source] of result.partials) {
    Handlebars.registerPartial(name, source);
  }

  return result;
}

export function renderPage(
  page: Page,
  template: HandlebarsTemplateDelegate,
  allPages: Page[],
  config: SiteConfig,
): string {
  const sorted = [...allPages]
    .filter((p) => !p.isDraft)
    .sort((a, b) => {
      const da = a.frontmatter.date ?? "";
      const db = b.frontmatter.date ?? "";
      return db.localeCompare(da);
    });

  return template({
    page,
    pages: sorted,
    config,
    title: page.frontmatter.title,
    date: page.frontmatter.date ?? null,
    tags: page.frontmatter.tags ?? [],
    content: page.html,
  });
}

export function renderTagPage(
  tagIndex: TagIndex,
  template: HandlebarsTemplateDelegate,
  config: SiteConfig,
): string {
  const sorted = [...tagIndex.pages].sort((a, b) => {
    const da = a.frontmatter.date ?? "";
    const db = b.frontmatter.date ?? "";
    return db.localeCompare(da);
  });

  return template({
    tag: tagIndex.tag,
    pages: sorted,
    config,
    title: `Tag: ${tagIndex.tag}`,
  });
}

export function renderIndex(
  pages: Page[],
  template: HandlebarsTemplateDelegate,
  config: SiteConfig,
): string {
  const sorted = [...pages]
    .filter((p) => !p.isDraft)
    .sort((a, b) => {
      const da = a.frontmatter.date ?? "";
      const db = b.frontmatter.date ?? "";
      return db.localeCompare(da);
    });

  return template({
    pages: sorted,
    config,
    title: config.title,
  });
}

import type { Page, TagIndex } from "./types.js";

export function buildTagIndex(pages: Page[]): Map<string, Page[]> {
  const map = new Map<string, Page[]>();

  for (const page of pages) {
    if (page.isDraft) continue;
    const tags = page.frontmatter.tags ?? [];
    for (const tag of tags) {
      const existing = map.get(tag);
      if (existing) {
        existing.push(page);
      } else {
        map.set(tag, [page]);
      }
    }
  }

  return map;
}

export function tagIndexToArray(map: Map<string, Page[]>): TagIndex[] {
  return [...map.entries()].map(([tag, pages]) => ({ tag, pages }));
}

import type { Page, SiteConfig } from "./types.js";

export function generateRSS(pages: Page[], config: SiteConfig): string {
  const published = pages
    .filter((p) => !p.isDraft)
    .sort((a, b) => {
      const da = a.frontmatter.date ?? "";
      const db = b.frontmatter.date ?? "";
      return db.localeCompare(da);
    });

  const items = published
    .slice(0, 20)
    .map((p) => {
      const link = `${config.baseUrl.replace(/\/$/, "")}/${p.slug}.html`;
      const date = p.frontmatter.date
        ? new Date(p.frontmatter.date).toUTCString()
        : new Date().toUTCString();
      const tags = (p.frontmatter.tags ?? [])
        .map((t) => `<category>${escapeXML(t)}</category>`)
        .join("\n      ");

      return `    <item>
      <title>${escapeXML(p.frontmatter.title)}</title>
      <link>${escapeXML(link)}</link>
      <guid isPermaLink="true">${escapeXML(link)}</guid>
      <pubDate>${date}</pubDate>
      ${tags}
      <description>${escapeXML(p.html.slice(0, 500))}</description>
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXML(config.title)}</title>
    <description>${escapeXML(config.description)}</description>
    <link>${escapeXML(config.baseUrl)}</link>
    <atom:link href="${escapeXML(config.baseUrl)}/rss.xml" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>`;
}

function escapeXML(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import { watch } from "chokidar";

const RELOAD_SCRIPT = `
<script>
(function() {
  var socket = new WebSocket('ws://' + location.host + '/__livereload');
  socket.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
})();
</script>
</body>`;

function injectReloadScript(html: string): string {
  return html.replace("</body>", RELOAD_SCRIPT);
}

export async function startDevServer(
  outputDir: string,
  sourceDir: string,
  rebuild: () => Promise<void>,
  port: number = 8080,
): Promise<{ server: http.Server; wss: WebSocketServer }> {
  const server = http.createServer(async (req, res) => {
    let urlPath = req.url ?? "/";
    if (urlPath === "/") urlPath = "/index.html";

    const filePath = path.join(outputDir, urlPath);

    try {
      const content = await fs.readFile(filePath);
      const ext = path.extname(filePath);
      const mimeTypes: Record<string, string> = {
        ".html": "text/html",
        ".css": "text/css",
        ".js": "application/javascript",
        ".xml": "application/xml",
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".svg": "image/svg+xml",
      };
      const contentType = mimeTypes[ext] ?? "application/octet-stream";

      let body = content;
      if (ext === ".html") {
        body = Buffer.from(injectReloadScript(content.toString()));
      }

      res.writeHead(200, { "Content-Type": contentType });
      res.end(body);
    } catch {
      res.writeHead(404);
      res.end("Not found");
    }
  });

  const wss = new WebSocketServer({ server });

  wss.on("connection", (ws: WebSocket) => {
    ws.send("connected");
  });

  function triggerReload() {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send("reload");
      }
    }
  }

  const watcher = watch(sourceDir, {
    ignoreInitial: true,
  });

  watcher.on("all", async (_event, _filePath) => {
    try {
      await rebuild();
      triggerReload();
    } catch (err) {
      console.error("Build error:", err);
    }
  });

  return new Promise((resolve) => {
    server.listen(port, () => {
      console.log(`Dev server running at http://localhost:${port}`);
      resolve({ server, wss });
    });
  });
}

import fs from "node:fs/promises";
import path from "node:path";
import { glob } from "node:fs/promises";
import type { SiteConfig, Page } from "./types.js";
import { parseFile } from "./parser.js";
import { renderMarkdown } from "./renderer.js";
import { compileTemplates, renderPage, renderTagPage, renderIndex } from "./template.js";
import { buildTagIndex, tagIndexToArray } from "./tags.js";
import { generateRSS } from "./rss.js";

async function collectPages(
  sourceDir: string,
  outputDir: string,
): Promise<Page[]> {
  const pages: Page[] = [];
  const pattern = path.join(sourceDir, "**/*.md");
  const files = glob(pattern);

  for await (const file of files) {
    const page = await parseFile(file, sourceDir, outputDir);
    pages.push(page);
  }

  return pages.sort((a, b) => {
    const da = a.frontmatter.date ?? "";
    const db = b.frontmatter.date ?? "";
    return db.localeCompare(da);
  });
}

export async function buildSite(config: SiteConfig): Promise<void> {
  await fs.mkdir(config.outputDir, { recursive: true });

  const pages = await collectPages(config.sourceDir, config.outputDir);

  for (const page of pages) {
    page.html = renderMarkdown(page.content);
  }

  const { templates } = await compileTemplates(config.templateDir);
  const mainTemplate =
    templates.get("layout") ??
    templates.get("default") ??
    templates.get("post") ??
    [...templates.values()][0];

  if (!mainTemplate) {
    throw new Error(
      `No template found in ${config.templateDir}. Add a layout.hbs, default.hbs, or post.hbs template.`,
    );
  }

  const published = pages.filter((p) => !p.isDraft);

  // Render individual pages
  for (const page of published) {
    const html = renderPage(page, mainTemplate, pages, config);
    const dir = path.dirname(page.outputPath);
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(page.outputPath, html);
  }

  // Render index page
  const indexTemplate = templates.get("index");
  if (indexTemplate) {
    const indexHtml = renderIndex(pages, indexTemplate, config);
    await fs.writeFile(path.join(config.outputDir, "index.html"), indexHtml);
  }

  // Render tag pages
  const tagTemplate = templates.get("tag");
  const tagMap = buildTagIndex(pages);
  if (tagTemplate) {
    const tagDir = path.join(config.outputDir, "tags");
    await fs.mkdir(tagDir, { recursive: true });
    for (const tagIndex of tagIndexToArray(tagMap)) {
      const html = renderTagPage(tagIndex, tagTemplate, config);
      const safeTag = tagIndex.tag.replace(/[^a-zA-Z0-9-]/g, "-");
      await fs.writeFile(path.join(tagDir, `${safeTag}.html`), html);
    }
  }

  // Generate RSS
  const feed = generateRSS(pages, config);
  await fs.writeFile(path.join(config.outputDir, "rss.xml"), feed);

  console.log(
    `Built ${published.length} page(s), ${tagMap.size} tag(s) to ${config.outputDir}`,
  );
}

#!/usr/bin/env node
import { Command } from "commander";
import type { SiteConfig } from "./types.js";
import { buildSite } from "./builder.js";
import { startDevServer } from "./server.js";

const program = new Command();

program
  .name("staticsite")
  .description("Static site generator")
  .version("1.0.0")
  .requiredOption("-s, --source <dir>", "source directory of markdown files")
  .requiredOption("-t, --templates <dir>", "template directory")
  .requiredOption("-o, --output <dir>", "output directory")
  .option("--title <title>", "site title", "My Site")
  .option("--description <desc>", "site description", "")
  .option("--base-url <url>", "base URL for RSS", "http://localhost:8080")
  .option("--serve", "start dev server with live reload")
  .option("--port <port>", "dev server port", "8080")
  .action(async (opts) => {
    const config: SiteConfig = {
      title: opts.title,
      description: opts.description,
      baseUrl: opts.baseUrl,
      sourceDir: opts.source,
      templateDir: opts.templates,
      outputDir: opts.output,
    };

    const rebuild = () => buildSite(config);

    if (opts.serve) {
      await rebuild();
      await startDevServer(
        config.outputDir,
        config.sourceDir,
        rebuild,
        parseInt(opts.port, 10),
      );
    } else {
      await buildSite(config);
    }
  });

program.parse();

export { parseFile, parseFrontmatter } from "./parser.js";
export { renderMarkdown } from "./renderer.js";
export { compileTemplates, renderPage, renderTagPage, renderIndex } from "./template.js";
export { buildTagIndex, tagIndexToArray } from "./tags.js";
export { generateRSS } from "./rss.js";
export { buildSite } from "./builder.js";
export { startDevServer } from "./server.js";
export type { Frontmatter, Page, TagIndex, BuildContext, SiteConfig } from "./types.js";

