import { describe, it, expect } from "vitest";
import { parseFrontmatter } from "../src/parser.js";

describe("parseFrontmatter", () => {
  it("parses YAML frontmatter with title", () => {
    const input = `---
title: Hello World
---
Some content here.`;

    const { data, content } = parseFrontmatter(input);
    expect(data.title).toBe("Hello World");
    expect(content).toBe("Some content here.\n");
  });

  it("handles missing title gracefully", () => {
    const input = `---
date: 2024-01-01
---
Content.`;

    const { data } = parseFrontmatter(input);
    expect(data.title).toBe("Untitled");
    expect(data.date).toBe("2024-01-01");
  });

  it("parses tags as array", () => {
    const input = `---
title: Post
tags:
  - typescript
  - ssg
---
Body.`;

    const { data } = parseFrontmatter(input);
    expect(data.tags).toEqual(["typescript", "ssg"]);
  });

  it("parses tags as comma-separated string", () => {
    const input = `---
title: Post
tags: js, ts, css
---
Body.`;

    const { data } = parseFrontmatter(input);
    expect(data.tags).toEqual(["js", "ts", "css"]);
  });

  it("parses draft boolean", () => {
    const input = `---
title: Draft Post
draft: true
---
Hidden.`;

    const { data } = parseFrontmatter(input);
    expect(data.draft).toBe(true);
  });

  it("draft defaults to false when omitted", () => {
    const input = `---
title: Published
---
Visible.`;

    const { data } = parseFrontmatter(input);
    expect(data.draft).toBeUndefined();
  });

  it("preserves extra frontmatter fields", () => {
    const input = `---
title: Extra
author: Alice
rating: 5
---
Extra content.`;

    const { data } = parseFrontmatter(input);
    expect(data.author).toBe("Alice");
    expect(data.rating).toBe(5);
  });

  it("parses date as string", () => {
    const input = `---
title: Dated
date: 2025-06-15
---
Content.`;

    const { data } = parseFrontmatter(input);
    expect(data.date).toBe("2025-06-15");
  });

  it("handles empty frontmatter", () => {
    const input = `---
---
Just content with no metadata.`;

    const { data, content } = parseFrontmatter(input);
    expect(data.title).toBe("Untitled");
    expect(content).toBe("Just content with no metadata.\n");
  });

  it("handles content with no frontmatter", () => {
    const input = "Plain markdown without frontmatter.";
    const { data, content } = parseFrontmatter(input);
    expect(data.title).toBe("Untitled");
    expect(content).toBe("Plain markdown without frontmatter.");
  });
});

import { describe, it, expect } from "vitest";
import { renderMarkdown } from "../src/renderer.js";

describe("renderMarkdown", () => {
  it("renders basic markdown", () => {
    const result = renderMarkdown("# Hello");
    expect(result).toContain("<h1");
    expect(result).toContain("Hello");
  });

  it("renders paragraphs", () => {
    const result = renderMarkdown("This is a paragraph.");
    expect(result).toContain("<p>");
    expect(result).toContain("This is a paragraph.");
  });

  it("renders bold and italic", () => {
    const result = renderMarkdown("**bold** and *italic*");
    expect(result).toContain("<strong>bold</strong>");
    expect(result).toContain("<em>italic</em>");
  });

  it("renders links", () => {
    const result = renderMarkdown("[link](https://example.com)");
    expect(result).toContain('<a href="https://example.com">');
    expect(result).toContain("link");
  });

  it("renders code spans", () => {
    const result = renderMarkdown("Use the `code` function.");
    expect(result).toContain("<code>code</code>");
  });

  it("renders fenced code blocks with syntax highlighting", () => {
    const result = renderMarkdown("```ts\nconst x = 1;\n```");
    expect(result).toContain("hljs");
    expect(result).toContain("language-ts");
    expect(result).toContain("const x");
  });

  it("renders fenced code blocks without language", () => {
    const result = renderMarkdown("```\nplain text\n```");
    expect(result).toContain("plain text");
  });

  it("renders unordered lists", () => {
    const result = renderMarkdown("- item 1\n- item 2");
    expect(result).toContain("<ul>");
    expect(result).toContain("<li>item 1</li>");
    expect(result).toContain("<li>item 2</li>");
  });

  it("renders ordered lists", () => {
    const result = renderMarkdown("1. first\n2. second");
    expect(result).toContain("<ol>");
    expect(result).toContain("<li>first</li>");
    expect(result).toContain("<li>second</li>");
  });

