---
# CLI Post`,
  );

  const cliPath = path.resolve("dist/cli.js");

  return { baseDir, srcDir, tmplDir, outDir, cliPath };
}

function runCli(args: string): string {
  try {
    return execSync(`node dist/cli.js ${args}`, {
      encoding: "utf-8",
      stdio: "pipe",
    });
  } catch (e: unknown) {
    const execErr = e as { stdout?: string; stderr?: string; message?: string };
    return (
      execErr.stdout ?? execErr.stderr ?? "CLI error: " + (execErr.message ?? "")
    );
  }
}

